-- =============================================================================
-- 2026_08_29_159 — SCHOOLS FOR THE WHOLE COUNTRY EXCEPT BAKI.
--
-- WHY THIS EXISTS. Migration 158 added 61 missing districts, but a district
-- with no schools is exactly as unusable as a missing district: school is
-- REQUIRED when a parent creates a child (web-app/src/lib/auth/children.ts
-- rejects a missing school for the web form and the mobile BFF alike). Adding
-- the districts without the schools would have moved the dead end, not removed
-- it. Before this, 14 of 15 districts had zero schools; all 320 were in Bakı.
--
-- SOURCE: the Ministry of Science and Education's own school register,
-- published as CC0 open data through the national open-data portal's CKAN API
-- and extracted to supabase/seed/schools_2026.json. Columns used: Məktəbin adı,
-- Rayon, Əsas tabeçilik, Təhsil müəssisəsinin tipi. Nothing is invented — every
-- row is a row of that file, and the owner's brief is explicit that a school
-- which cannot be verified must be reported as a gap rather than fabricated.
--
-- KNOWN GAP, stated rather than hidden: the register carries 3805 rows
-- against an official national count of 4,357, i.e. roughly 160 short. The
-- shortfall is NOT evenly spread — it is concentrated in districts where schools
-- are still being reopened (Ağdam, Laçın, Şuşa, Füzuli, Xocavənd). Those
-- districts are under-covered here and will fill in when the ministry refreshes.
--
-- BAKI IS DELIBERATELY EXCLUDED and gets its own migration. Its 393 rows must
-- reconcile against the 320 schools already seeded in 012, and the collision is
-- invisible to a name comparison: 178 of them are the SAME physical school
-- wearing an honorific ("Bakı şəhəri Ə.Səmədov adına 12 nömrəli tam orta
-- ümumtəhsil məktəbi" against the seeded "Bakı 12 nömrəli tam orta məktəb").
-- Importing them by name would put roughly 190 duplicate schools into the Bakı
-- picker. That reconciliation keys on school NUMBER and is its own reviewable
-- change.
--
-- TWO REPAIRS APPLIED TO THE SOURCE TEXT, both recorded because an unexplained
-- transform is a bug someone has to reverse-engineer later:
--   1. 36 names contained CYRILLIC letters typed in place of their Latin
--      lookalikes — "ümumi оrtа məktəbi" with U+043E and U+0430, concentrated in
--      Samux, Qusar and Xaçmaz. That is a defect in the ministry's own file. It
--      is repaired, not preserved: a parent typing "orta" would never find those
--      schools, and the (district_id, lower(name)) unique index cannot see two
--      spellings of one name as a duplicate, so a future genuine collision would
--      slip past it.
--   2. Internal double spaces collapsed. Cosmetic, harmless to the index.
-- Diacritics, honorifics, "nömrəli"/"saylı" spelling and word order are left
-- EXACTLY as the ministry published them.
--
-- XIRDALAN. The classification places it inside Abşeron rayonu, but it is a city
-- of roughly 100,000 that residents identify with and it is a selectable
-- location. The 11 schools whose names carry "Xırdalan şəhəri" are assigned
-- to it rather than to Abşeron, so choosing it does not lead to an empty list.
--
-- SCHOOLS IN THE LIBERATED TERRITORIES ARE INCLUDED AS PUBLISHED. The register
-- is de jure: some of these are registered but not yet physically operating, or
-- operating in displacement. They are correctly sourced and excluding them would
-- be a political judgement this migration has no business making.
--
-- city_district_id IS NULL FOR EVERY ROW, and that is correct: Bakı is the only
-- city with intra-city rayons, so `school_district_guard` (003) does not require
-- one here. It would REJECT a null rayon for a Bakı school — another reason Bakı
-- is not in this file.
--
-- Rerun-safe: `on conflict (district_id, lower(name)) do nothing`.
--
-- Environment first applied: staging
-- Related root SQL file(s) / BACKPORT TARGETS:
--          * 012_seed_initial_data.sql — reference this migration in the school
--            seed section the way the curriculum tree is referenced, rather than
--            inlining 3805 VALUES rows into the canonical file.
-- Backport status: completed
-- Destructive change: no. Insert-only; no existing row is updated or deleted.
-- =============================================================================
begin;

create temp table _schools_159 (
  name          text    not null,
  rayon         text    not null,
  school_number int,
  is_private    boolean not null
) on commit drop;

