-- Every rayon must resolve to a district BEFORE anything is inserted, so a
-- typo or a missing division fails loudly instead of silently dropping schools.
do $$
declare
  v_bad text;
begin
  select string_agg(distinct t.rayon, ', ') into v_bad
  from _schools_159 t
  where not exists (
    select 1 from public.districts d
    where d.country_code = 'AZ' and d.name = t.rayon
  );
  if v_bad is not null then
    raise exception '159: these rayons do not resolve to a district: %', v_bad;
  end if;
end;
$$;

insert into public.schools (name, district_id, city_district_id, status,
                            is_private, school_number)
select t.name, d.id, null, 'active', t.is_private, t.school_number
from _schools_159 t
join public.districts d
  on d.country_code = 'AZ' and d.name = t.rayon
on conflict (district_id, lower(name)) do nothing;

-- -----------------------------------------------------------------------------
-- VERIFICATION. Coverage, not just "it ran".
-- -----------------------------------------------------------------------------
do $$
declare
  v_schools int;
  v_empty   text;
  v_baku    int;
begin
  select count(*) into v_schools from public.schools;
  if v_schools < 3500 then
    raise exception '159: only % schools present, expected 3500+', v_schools;
  end if;

  -- Bakı must be untouched by this file: still exactly its seeded 320.
  select count(*) into v_baku
  from public.schools s
  join public.districts d on d.id = s.district_id
  where d.name = 'Bakı';
  if v_baku <> 320 then
    raise exception
      '159: Bakı school count changed to % (expected the seeded 320) — this '
      'migration must not touch Bakı', v_baku;
  end if;

  -- Which districts a parent can still select but find nothing in. Reported,
  -- not raised: the register genuinely under-covers the reopening districts,
  -- and failing here would block a correct import over a known data gap.
  select string_agg(d.name, ', ' order by d.name) into v_empty
  from public.districts d
  where d.country_code = 'AZ'
    and not exists (select 1 from public.schools s
                     where s.district_id = d.id and s.status = 'active');
  if v_empty is not null then
    raise notice '159: districts still with no active school: %', v_empty;
  end if;

  raise notice '159: % schools total across the country', v_schools;
end;
$$;

commit;
